**Q1. Define the property graph model and implement it in Python.**

```python
from dataclasses import dataclass, field
from typing import Any, Optional
import uuid

@dataclass
class Node:
    id: str
    label: str                              # Entity type (Company, Person, etc.)
    properties: dict[str, Any] = field(default_factory=dict)

    def __hash__(self): return hash(self.id)
    def __eq__(self, other): return self.id == other.id

@dataclass
class Edge:
    id: str
    source_id: str
    target_id: str
    relation_type: str
    properties: dict[str, Any] = field(default_factory=dict)

    def __hash__(self): return hash(self.id)

class PropertyGraph:
    """In-memory property graph implementation."""

    def __init__(self):
        self._nodes: dict[str, Node] = {}
        self._edges: dict[str, Edge] = {}
        self._adj: dict[str, set[str]] = {}        # node_id → set of edge_ids (out)
        self._in_adj: dict[str, set[str]] = {}     # node_id → set of edge_ids (in)
        self._node_to_edges: dict[str, set[str]] = {}

    def add_node(self, label: str, properties: dict = None, node_id: str = None) -> Node:
        nid = node_id or str(uuid.uuid4())
        node = Node(id=nid, label=label, properties=properties or {})
        self._nodes[nid] = node
        self._adj[nid] = set()
        self._in_adj[nid] = set()
        return node

    def add_edge(
        self,
        source_id: str,
        target_id: str,
        relation_type: str,
        properties: dict = None
    ) -> Edge:
        if source_id not in self._nodes or target_id not in self._nodes:
            raise ValueError(f"Node not found: {source_id} or {target_id}")
        eid = str(uuid.uuid4())
        edge = Edge(
            id=eid,
            source_id=source_id,
            target_id=target_id,
            relation_type=relation_type,
            properties=properties or {}
        )
        self._edges[eid] = edge
        self._adj[source_id].add(eid)
        self._in_adj[target_id].add(eid)
        return edge

    def get_neighbours(
        self, node_id: str, relation_filter: Optional[str] = None
    ) -> list[tuple[Node, Edge]]:
        """Get (neighbour_node, edge) pairs for outgoing edges."""
        result = []
        for eid in self._adj.get(node_id, set()):
            edge = self._edges[eid]
            if relation_filter and edge.relation_type != relation_filter:
                continue
            neighbour = self._nodes[edge.target_id]
            result.append((neighbour, edge))
        return result

    def k_hop_subgraph(self, start_id: str, k: int) -> "PropertyGraph":
        """Extract k-hop neighbourhood as a new PropertyGraph."""
        subgraph = PropertyGraph()
        visited_nodes: set[str] = set()
        queue = [(start_id, 0)]

        while queue:
            node_id, depth = queue.pop(0)
            if node_id in visited_nodes or depth > k:
                continue
            visited_nodes.add(node_id)
            node = self._nodes[node_id]
            subgraph.add_node(node.label, node.properties, node.id)

            if depth < k:
                for neighbour, edge in self.get_neighbours(node_id):
                    if neighbour.id not in visited_nodes:
                        queue.append((neighbour.id, depth + 1))
                    # Add edge to subgraph
                    if (neighbour.id in visited_nodes or
                            any(e.source_id == node_id for e in subgraph._edges.values())):
                        try:
                            subgraph.add_edge(
                                node_id, neighbour.id,
                                edge.relation_type, edge.properties
                            )
                        except ValueError:
                            pass  # Neighbour not yet in subgraph

        return subgraph

    def to_networkx(self):
        """Convert to NetworkX for algorithm support."""
        import networkx as nx
        G = nx.MultiDiGraph()
        for node in self._nodes.values():
            G.add_node(node.id, label=node.label, **node.properties)
        for edge in self._edges.values():
            G.add_edge(
                edge.source_id, edge.target_id,
                relation=edge.relation_type, **edge.properties
            )
        return G
```

**Q2. What is an RDF triple and how does it differ from a property graph edge?**

**A:** An RDF triple is a (subject, predicate, object) statement where ALL three components are URIs (or literals for objects). RDF has no built-in mechanism for edge properties — to add metadata to a relationship, you must use reification (creating a new node to represent the statement) or RDF-star extensions. Property graphs allow rich properties directly on edges (weight, timestamp, confidence) making them more natural for Graph RAG where relationship metadata is important.

```python
from dataclasses import dataclass
from typing import Union

# RDF model
@dataclass
class RDFTriple:
    subject: str    # URI, e.g., "https://example.org/Apple_Inc"
    predicate: str  # URI, e.g., "https://example.org/employs"
    obj: Union[str, int, float, bool]  # URI or literal

    def to_turtle(self) -> str:
        """Serialise to Turtle format."""
        if isinstance(self.obj, str) and self.obj.startswith("http"):
            obj_str = f"<{self.obj}>"
        elif isinstance(self.obj, str):
            obj_str = f'"{self.obj}"'
        else:
            obj_str = str(self.obj)
        return f"<{self.subject}> <{self.predicate}> {obj_str} ."

# RDF reification to add edge metadata (verbose!)
def reify_triple(triple: RDFTriple, confidence: float) -> list[RDFTriple]:
    """RDF reification: add metadata to a triple (ugly but standard)."""
    stmt_id = f"https://example.org/statements/{hash(triple)}"
    rdf = "http://www.w3.org/1999/02/22-rdf-syntax-ns#"
    return [
        RDFTriple(stmt_id, f"{rdf}type", f"{rdf}Statement"),
        RDFTriple(stmt_id, f"{rdf}subject", triple.subject),
        RDFTriple(stmt_id, f"{rdf}predicate", triple.predicate),
        RDFTriple(stmt_id, f"{rdf}object", triple.obj),
        RDFTriple(stmt_id, "https://example.org/confidence", confidence),
    ]

# Property graph edge with metadata (clean and natural)
@dataclass
class PropertyEdge:
    source: str
    relation: str
    target: str
    confidence: float      # Directly on edge — clean!
    timestamp: str
    source_document: str
    # Can add any metadata without reification
```

**Q3. What is a hypergraph and when does Graph RAG need one?**

**A:** A hypergraph generalises the graph concept by allowing **hyperedges** that connect more than two nodes simultaneously. Standard edges are binary (A→B); hyperedges are n-ary (A, B, C, D are all related by a single relationship). In Graph RAG, hyperedges are needed when a single relationship involves multiple entities: a contract between 3 companies, a scientific experiment with multiple authors and subjects, a merger involving acquirer, target, and regulator. Hypergraphs can be converted to standard property graphs through **reification** (creating a node for the hyperedge itself).

```python
from dataclasses import dataclass, field
from typing import Any

@dataclass
class Hyperedge:
    """A relationship involving multiple nodes simultaneously."""
    id: str
    relation_type: str
    nodes: list[str]          # All participating entities
    properties: dict[str, Any] = field(default_factory=dict)

class Hypergraph:
    def __init__(self):
        self.nodes: dict[str, dict] = {}
        self.hyperedges: dict[str, Hyperedge] = {}

    def add_hyperedge(
        self,
        relation_type: str,
        participating_nodes: list[str],
        properties: dict = None
    ) -> Hyperedge:
        import uuid
        hid = str(uuid.uuid4())
        he = Hyperedge(
            id=hid,
            relation_type=relation_type,
            nodes=participating_nodes,
            properties=properties or {}
        )
        self.hyperedges[hid] = he
        return he

    def to_property_graph(self) -> PropertyGraph:
        """
        Convert hypergraph to standard property graph via REIFICATION.
        Each hyperedge becomes an intermediate node.
        """
        pg = PropertyGraph()

        # Add original nodes
        for node_id, props in self.nodes.items():
            pg.add_node(label=props.get("type", "Entity"),
                       properties=props, node_id=node_id)

        # Add hyperedge as intermediate node + star edges
        for he in self.hyperedges.values():
            # Create a node representing the hyperedge event
            he_node = pg.add_node(
                label=f"Event_{he.relation_type}",
                properties={
                    "event_type": he.relation_type,
                    **he.properties
                },
                node_id=he.id
            )
            # Connect all participants to this event node
            for participant_id in he.nodes:
                if participant_id in pg._nodes:
                    pg.add_edge(
                        source_id=participant_id,
                        target_id=he_node.id,
                        relation_type="PARTICIPATES_IN"
                    )

        return pg

# Example: 3-way merger between companies
def model_merger(
    acquirer: str, target: str, regulator: str,
    merger_date: str, value_usd_bn: float
) -> Hyperedge:
    hg = Hypergraph()
    return hg.add_hyperedge(
        relation_type="MERGER",
        participating_nodes=[acquirer, target, regulator],
        properties={
            "date": merger_date,
            "value_usd_bn": value_usd_bn,
            "role_map": {
                acquirer: "ACQUIRER",
                target: "TARGET",
                regulator: "REGULATOR"
            }
        }
    )
```

**Q4. When do you choose a property graph vs RDF for a Graph RAG system?**

**A:** Choose **property graph** when: you need rich edge metadata (confidence, timestamps, source docs), you use Cypher/Gremlin queries, you need fast multi-hop traversal, your team has no RDF/SPARQL expertise. Choose **RDF** when: you need semantic web interoperability (OWL, RDFS reasoning), your data must conform to W3C standards, you're integrating with existing linked data (DBpedia, Wikidata), or you need formal ontological inference.

```python
from enum import Enum
from dataclasses import dataclass

class GraphModel(Enum):
    PROPERTY_GRAPH = "property_graph"
    RDF = "rdf"
    RDF_STAR = "rdf_star"  # RDF with edge properties (modern RDF extension)

@dataclass
class ModelSelectionCriteria:
    needs_edge_properties: bool
    needs_semantic_reasoning: bool
    team_has_sparql_expertise: bool
    needs_linked_data_integration: bool
    query_language_preference: str  # "cypher", "sparql", "gremlin"
    priority_latency: bool

def select_graph_model(criteria: ModelSelectionCriteria) -> tuple[GraphModel, str]:
    """Rule-based model selection."""
    reasons = []

    if criteria.needs_edge_properties and not criteria.needs_semantic_reasoning:
        reasons.append("Edge properties needed without semantic reasoning → Property Graph")
        return GraphModel.PROPERTY_GRAPH, "; ".join(reasons)

    if criteria.needs_semantic_reasoning and criteria.needs_linked_data_integration:
        if criteria.needs_edge_properties:
            reasons.append("Semantic reasoning + edge properties → RDF-star")
            return GraphModel.RDF_STAR, "; ".join(reasons)
        reasons.append("Full semantic reasoning + linked data → RDF")
        return GraphModel.RDF, "; ".join(reasons)

    if criteria.query_language_preference == "cypher":
        return GraphModel.PROPERTY_GRAPH, "Team prefers Cypher → Property Graph (Neo4j)"

    if criteria.priority_latency:
        reasons.append("Low latency priority → Property Graph (faster traversal)")
        return GraphModel.PROPERTY_GRAPH, "; ".join(reasons)

    return GraphModel.PROPERTY_GRAPH, "Default: Property Graph for Graph RAG"

# Tradeoff table
TRADEOFFS = {
    "Property Graph": {
        "pros": ["Rich edge properties", "Fast traversal", "Cypher/Gremlin", "Intuitive"],
        "cons": ["No semantic reasoning", "Not W3C standard", "Vendor lock-in"],
        "use_cases": ["Graph RAG", "Fraud detection", "Recommendation", "Social networks"]
    },
    "RDF": {
        "pros": ["W3C standard", "OWL reasoning", "Linked data", "SPARQL"],
        "cons": ["Verbose", "Slow for large traversals", "Edge properties require reification"],
        "use_cases": ["Knowledge bases", "Biomedical", "Government data", "Linked data"]
    }
}
```

**Q5. Explain heterogeneous graphs and their role in Graph RAG.**

**A:** A **heterogeneous graph** has multiple node types and multiple edge types, as opposed to homogeneous graphs where all nodes and edges are the same type. In Graph RAG, knowledge graphs are inherently heterogeneous: nodes can be Person, Company, Product, Location, Event; edges can be EMPLOYS, PRODUCES, LOCATED_IN, ACQUIRED. This heterogeneity is crucial because retrieval algorithms must be type-aware — you shouldn't traverse a LOCATED_IN edge the same way as an EMPLOYS edge when answering employment-related queries.

```python
import networkx as nx
from collections import defaultdict
from typing import Callable

class HeterogeneousGraph:
    """Type-aware heterogeneous graph for Graph RAG."""

    def __init__(self):
        self.G = nx.MultiDiGraph()
        self.node_type_index: defaultdict[str, set[str]] = defaultdict(set)
        self.edge_type_index: defaultdict[str, list[tuple]] = defaultdict(list)

    def add_node(self, node_id: str, node_type: str, **properties) -> None:
        self.G.add_node(node_id, node_type=node_type, **properties)
        self.node_type_index[node_type].add(node_id)

    def add_edge(
        self,
        src: str, dst: str, edge_type: str, **properties
    ) -> None:
        self.G.add_edge(src, dst, edge_type=edge_type, **properties)
        self.edge_type_index[edge_type].append((src, dst))

    def get_nodes_by_type(self, node_type: str) -> list[str]:
        return list(self.node_type_index[node_type])

    def type_constrained_traversal(
        self,
        start_node: str,
        allowed_edge_types: list[str],
        allowed_target_types: list[str],
        max_hops: int = 2
    ) -> list[str]:
        """Traversal constrained by edge and node type — type-aware retrieval."""
        visited = set()
        result = []
        queue = [(start_node, 0)]

        while queue:
            node_id, depth = queue.pop(0)
            if node_id in visited or depth > max_hops:
                continue
            visited.add(node_id)
            result.append(node_id)

            for _, neighbour_id, data in self.G.out_edges(node_id, data=True):
                edge_type = data.get("edge_type")
                target_type = self.G.nodes[neighbour_id].get("node_type")

                if (edge_type in allowed_edge_types and
                        target_type in allowed_target_types):
                    queue.append((neighbour_id, depth + 1))

        return result

    def meta_path_query(
        self,
        start_node: str,
        meta_path: list[tuple[str, str]]  # [(edge_type, node_type), ...]
    ) -> list[list[str]]:
        """
        Meta-path traversal for heterogeneous graphs.
        Example: Person -EMPLOYED_BY-> Company -INVESTED_IN-> Fund
        meta_path = [("EMPLOYED_BY", "Company"), ("INVESTED_IN", "Fund")]
        """
        paths = [[start_node]]

        for edge_type, target_type in meta_path:
            new_paths = []
            for path in paths:
                current = path[-1]
                for _, nbr, data in self.G.out_edges(current, data=True):
                    if (data.get("edge_type") == edge_type and
                            self.G.nodes[nbr].get("node_type") == target_type):
                        new_paths.append(path + [nbr])
            paths = new_paths

        return paths
```

**Q6. What are the major graph serialisation formats and when would you use each?**

**A:** **JSON-LD** — linked data in JSON, widely adopted for web APIs and semantic markup. **Turtle** — compact human-readable RDF, good for configuration and small KBs. **N-Triples** — one triple per line, streaming-friendly for bulk loads. **GraphML** — XML-based, used by Gephi and graph analytics tools. **Cypher CREATE** — Neo4j's native import format. For Graph RAG production: use **Parquet** for bulk data storage, **JSON-LD** for API interchange, and **N-Triples** for streaming batch imports.

```python
import json
from typing import IO

class GraphSerialiser:
    """Multi-format graph serialisation."""

    def to_json_ld(self, nodes: list[Node], edges: list[Edge]) -> str:
        """JSON-LD format for semantic web compatibility."""
        context = {
            "@vocab": "https://example.org/kg/",
            "name": "schema:name",
            "type": "@type",
        }
        graph_items = []

        for node in nodes:
            item = {
                "@id": f"https://example.org/kg/entity/{node.id}",
                "@type": node.label,
                **node.properties
            }
            graph_items.append(item)

        for edge in edges:
            item = {
                "@id": f"https://example.org/kg/relation/{edge.id}",
                "@type": edge.relation_type,
                "subject": {"@id": f"https://example.org/kg/entity/{edge.source_id}"},
                "object": {"@id": f"https://example.org/kg/entity/{edge.target_id}"},
                **edge.properties
            }
            graph_items.append(item)

        return json.dumps({"@context": context, "@graph": graph_items}, indent=2)

    def to_turtle(self, triples: list[RDFTriple]) -> str:
        """Compact Turtle RDF serialisation."""
        prefixes = "@prefix ex: <https://example.org/> .\n\n"
        return prefixes + "\n".join(t.to_turtle() for t in triples)

    def to_n_triples(self, triples: list[RDFTriple]) -> str:
        """N-Triples: one triple per line, streaming-friendly."""
        return "\n".join(
            f"<{t.subject}> <{t.predicate}> "
            f'{"<" + t.obj + ">" if isinstance(t.obj, str) and t.obj.startswith("http") else json.dumps(t.obj)} .'
            for t in triples
        )

    def to_cypher_create(self, nodes: list[Node], edges: list[Edge]) -> str:
        """Generate Neo4j Cypher CREATE statements for bulk import."""
        lines = []
        for node in nodes:
            props = json.dumps(node.properties)
            lines.append(
                f'CREATE (n_{node.id[:8]}:{node.label} '
                f'{{id: "{node.id}", {", ".join(f"{k}: {json.dumps(v)}" for k, v in node.properties.items())}}})'
            )
        for edge in edges:
            lines.append(
                f'MATCH (a {{id: "{edge.source_id}"}}), (b {{id: "{edge.target_id}"}}) '
                f'CREATE (a)-[:{edge.relation_type} '
                f'{{{", ".join(f"{k}: {json.dumps(v)}" for k, v in edge.properties.items())}}}]->(b)'
            )
        return "\n".join(lines)

    def to_parquet(
        self,
        nodes: list[Node],
        edges: list[Edge],
        output_dir: str
    ) -> None:
        """Bulk storage in Parquet for large-scale KG export."""
        import pandas as pd
        import os

        nodes_df = pd.DataFrame([
            {"id": n.id, "label": n.label, **n.properties}
            for n in nodes
        ])
        edges_df = pd.DataFrame([
            {"id": e.id, "source": e.source_id,
             "target": e.target_id, "relation": e.relation_type,
             **e.properties}
            for e in edges
        ])

        os.makedirs(output_dir, exist_ok=True)
        nodes_df.to_parquet(f"{output_dir}/nodes.parquet", index=False)
        edges_df.to_parquet(f"{output_dir}/edges.parquet", index=False)
```

**Q7. How do directed vs undirected graphs affect Graph RAG retrieval?**

**A:** **Directed graphs** encode asymmetric relationships (Apple ACQUIRED Instagram — not the reverse). **Undirected graphs** encode symmetric relationships (Apple IS_COMPETITOR Samsung). In Graph RAG, most knowledge graph relationships are **directed**: EMPLOYS, INVESTED_IN, PRODUCES. At retrieval time, you often want **bidirectional traversal** (from both source and target perspectives) because a user asking about "Apple's competitors" needs to traverse both COMPETES_WITH outgoing edges AND incoming COMPETES_WITH edges from other companies. The solution: store as directed, traverse in both directions at query time.

```python
import networkx as nx

def bidirectional_subgraph_extraction(
    G: nx.DiGraph,
    start_nodes: list[str],
    hops: int = 2,
    relation_filter: list[str] = None
) -> nx.DiGraph:
    """
    Extract subgraph using bidirectional traversal.
    Captures both incoming and outgoing relationships.
    """
    reachable: set[str] = set()

    for start in start_nodes:
        if start not in G:
            continue
        # Forward traversal (outgoing edges)
        forward = nx.single_source_shortest_path_length(G, start, cutoff=hops)
        reachable.update(forward.keys())

        # Backward traversal (incoming edges) — reverse the graph
        G_rev = G.reverse()
        backward = nx.single_source_shortest_path_length(G_rev, start, cutoff=hops)
        reachable.update(backward.keys())

    subgraph = G.subgraph(reachable).copy()

    # Filter by relation type if specified
    if relation_filter:
        edges_to_remove = [
            (u, v, k) for u, v, k, data in subgraph.edges(keys=True, data=True)
            if data.get("relation") not in relation_filter
        ]
        subgraph.remove_edges_from(edges_to_remove)

    return subgraph

# Symmetric relationship handling
def make_relationship_symmetric(
    G: nx.DiGraph,
    relation_type: str
) -> nx.DiGraph:
    """Add reverse edges for symmetric relationships."""
    new_edges = []
    for u, v, data in G.edges(data=True):
        if data.get("relation") == relation_type:
            # Add reverse edge if not already present
            if not G.has_edge(v, u):
                new_edges.append((v, u, {**data, "inferred_reverse": True}))
    G.add_edges_from(new_edges)
    return G
```

**Q8. How does graph density affect Graph RAG retrieval quality?**

**A:** **Low-density graphs** (sparse) have many isolated entities — retrieval finds relevant anchor nodes but the subgraph context is thin. **High-density graphs** (dense, many co-occurrence edges) cause context overflow — k-hop traversal explodes into thousands of nodes. Optimal Graph RAG graphs are **scale-free** (power-law degree distribution): a few hub entities (company names) have many connections, most entities have few. Tune density by: setting minimum relationship confidence thresholds, limiting co-occurrence edges, using typed relationships instead of generic ones.

```python
import networkx as nx
import numpy as np

def analyse_graph_density(G: nx.Graph) -> dict:
    """Graph density analysis for RAG suitability."""
    degrees = [d for _, d in G.degree()]
    degree_hist = np.bincount(degrees)

    # Check for scale-free property (power law)
    # log(degree) vs log(frequency) should be linear
    nonzero_degrees = [(d, c) for d, c in enumerate(degree_hist) if c > 0 and d > 0]

    return {
        "density": nx.density(G),
        "avg_degree": np.mean(degrees),
        "max_degree": max(degrees),
        "median_degree": np.median(degrees),
        "gini_coefficient": _gini(degrees),  # 0=uniform, 1=maximally unequal
        "is_scale_free": _check_power_law(nonzero_degrees),
        "hub_entities": [
            n for n, d in G.degree()
            if d > np.percentile(degrees, 95)
        ][:10],
        "rag_suitability": "good" if 0.01 < nx.density(G) < 0.1 else "poor"
    }

def _gini(values: list[float]) -> float:
    """Gini coefficient for degree distribution inequality."""
    arr = sorted(values)
    n = len(arr)
    if n == 0: return 0
    coef = 2 / n * sum((i + 1) * v for i, v in enumerate(arr))
    return coef / sum(arr) - (n + 1) / n

def _check_power_law(degree_freq: list[tuple]) -> bool:
    """Rough power-law check via log-log linearity."""
    if len(degree_freq) < 5:
        return False
    log_d = np.log([d for d, _ in degree_freq])
    log_f = np.log([f for _, f in degree_freq])
    corr = np.corrcoef(log_d, log_f)[0, 1]
    return corr < -0.7  # Strong negative log-log correlation = power law
```

**Q9. What is a knowledge graph embedding and how does it bridge graph and vector retrieval?**

**A:** Knowledge graph embeddings (TransE, RotatE, Node2Vec) map graph entities and relations into a continuous vector space while preserving structural relationships. TransE models relationships as translations: `embedding(head) + embedding(relation) ≈ embedding(tail)`. These embeddings enable: (1) semantic similarity search between entities in embedding space, (2) missing link prediction, (3) initialising GNN layers for complex graph learning. In hybrid Graph RAG, entity embeddings serve as the vector index, while graph structure provides traversal context — combining both retrieval signals.

```python
import numpy as np
from typing import Optional

class TransEEmbedding:
    """Simplified TransE knowledge graph embedding."""

    def __init__(self, embedding_dim: int = 128, margin: float = 1.0):
        self.dim = embedding_dim
        self.margin = margin
        self.entity_embs: dict[str, np.ndarray] = {}
        self.relation_embs: dict[str, np.ndarray] = {}

    def initialise(self, entities: list[str], relations: list[str]) -> None:
        """Random initialisation with L2 normalisation."""
        for e in entities:
            emb = np.random.randn(self.dim).astype(np.float32)
            self.entity_embs[e] = emb / np.linalg.norm(emb)
        for r in relations:
            emb = np.random.randn(self.dim).astype(np.float32)
            self.relation_embs[r] = emb / np.linalg.norm(emb)

    def score_triple(self, head: str, relation: str, tail: str) -> float:
        """TransE scoring: lower = more plausible triple."""
        if head not in self.entity_embs or tail not in self.entity_embs:
            return float("inf")
        h = self.entity_embs[head]
        r = self.relation_embs.get(relation, np.zeros(self.dim))
        t = self.entity_embs[tail]
        return float(np.linalg.norm(h + r - t))

    def predict_tail(
        self, head: str, relation: str, top_k: int = 5
    ) -> list[tuple[str, float]]:
        """Predict most likely tail entities for (head, relation, ?) queries."""
        if head not in self.entity_embs:
            return []
        h = self.entity_embs[head]
        r = self.relation_embs.get(relation, np.zeros(self.dim))
        target = h + r

        scores = []
        for entity, emb in self.entity_embs.items():
            if entity != head:
                dist = float(np.linalg.norm(emb - target))
                scores.append((entity, dist))

        return sorted(scores, key=lambda x: x[1])[:top_k]

    def find_similar_entities(
        self, entity: str, top_k: int = 10
    ) -> list[tuple[str, float]]:
        """Find structurally similar entities via embedding cosine similarity."""
        if entity not in self.entity_embs:
            return []
        query_emb = self.entity_embs[entity]
        scores = []
        for name, emb in self.entity_embs.items():
            if name != entity:
                sim = float(np.dot(query_emb, emb) / (
                    np.linalg.norm(query_emb) * np.linalg.norm(emb)
                ))
                scores.append((name, sim))
        return sorted(scores, key=lambda x: x[1], reverse=True)[:top_k]
```

**Q10. How do you design a graph schema that supports both efficient traversal and vector similarity search?**

**A:** Hybrid schema design: (1) Store entity embeddings as node properties (Neo4j vector index). (2) Use typed edges with weights (confidence, frequency) for traversal weighting. (3) Add community labels to nodes (fast community-level filtering). (4) Store text chunk references on edges for evidence retrieval. (5) Use composite indexes on (node_type, name) for fast entity lookup. (6) Partition graph by community ID for horizontal scaling.

```python
from pydantic import BaseModel
from typing import Optional
import numpy as np

class HybridEntityNode(BaseModel):
    """Node schema optimised for hybrid graph-vector retrieval."""
    id: str
    name: str
    entity_type: str
    description: str
    embedding: list[float]           # For vector similarity search
    community_id: int                # For community-level filtering
    community_level: int             # Hierarchy level (0, 1, 2)
    importance_score: float          # PageRank or degree-based
    source_document_ids: list[str]   # Provenance
    created_at: str
    updated_at: str

class HybridRelationEdge(BaseModel):
    """Edge schema optimised for hybrid retrieval."""
    source_id: str
    target_id: str
    relation_type: str
    weight: float                    # Strength (frequency, confidence)
    embedding: Optional[list[float]] # Edge embedding (TransE)
    source_chunk_ids: list[str]      # Evidence chunks
    confidence: float
    is_inferred: bool = False        # From ontology inference vs extracted

# Neo4j schema creation (Cypher)
SCHEMA_CREATION_CYPHER = """
// Create constraints
CREATE CONSTRAINT entity_id IF NOT EXISTS
FOR (e:Entity) REQUIRE e.id IS UNIQUE;

// Create vector index for semantic search
CREATE VECTOR INDEX entity_embedding IF NOT EXISTS
FOR (e:Entity) ON (e.embedding)
OPTIONS {indexConfig: {
  `vector.dimensions`: 384,
  `vector.similarity_function`: 'cosine'
}};

// Create composite index for fast type+name lookup
CREATE INDEX entity_type_name IF NOT EXISTS
FOR (e:Entity) ON (e.entity_type, e.name);

// Create community index
CREATE INDEX entity_community IF NOT EXISTS
FOR (e:Entity) ON (e.community_id, e.community_level);
"""
